INSERT INTO grupos (clave, docente_id, asignatura_id, cuatrimestre_id) SELECT 'Matutino', d.id, a.id, (SELECT id FROM cuatrimestres WHERE activo = true LIMIT 1) FROM docentes d, asignaturas a WHERE d.nombre || ' ' || d.apellidos ILIKE '%MARTINEZ LARA MARCO ANTONIO%' AND a.clave = 'AEP10' ON CONFLICT DO NOTHING;
